/** Writes generated files to disk. Shared by `compile` and gate 4 (drift), so both write identical bytes. */
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, relative } from 'node:path';
import type { GeneratedArtifact } from './plugins/plugin.interface.js';

export interface WrittenFile {
  readonly path: string;
  readonly changed: boolean;
}

/** Absolute path of a generated file under `outDir` (relative paths are POSIX). */
export function generatedPath(outDir: string, relativePath: string): string {
  return join(outDir, ...relativePath.split('/'));
}

/** Writes each file as UTF-8 (no BOM), skipping files whose content is already identical. */
export async function writeGeneratedFiles(
  outDir: string,
  files: readonly GeneratedArtifact[],
): Promise<WrittenFile[]> {
  const written: WrittenFile[] = [];
  for (const file of files) {
    const path = generatedPath(outDir, file.relativePath);
    const current = await readFile(path, 'utf8').catch(() => undefined);
    if (current === file.content) {
      written.push({ path, changed: false });
      continue;
    }
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, file.content, 'utf8');
    written.push({ path, changed: true });
  }
  return written;
}

/** The first text of every file that urn-forge writes (the header of src/engine.ts). */
const GENERATED_MARK = '// @generated by urn-forge ';

/** The `*.generated.*` files under `outDir`, as sorted POSIX paths relative to it. */
export async function listGeneratedFiles(outDir: string): Promise<string[]> {
  const entries = await readdir(outDir, { recursive: true, withFileTypes: true }).catch(() => []);
  return entries
    .filter((e) => e.isFile() && /\.generated\./.test(e.name))
    .map((e) => relative(outDir, join(e.parentPath, e.name)).split('\\').join('/'))
    .sort();
}

/**
 * Deletes the generated files under `outDir` that `files` does not include, for example
 * after an atom or a plugin was removed. Only files that start with urn-forge's header are
 * deleted; a hand-written `*.generated.*` file stays, and gate 4 reports it as an orphan.
 * Returns the absolute paths it deleted.
 */
export async function removeOrphanFiles(outDir: string, files: readonly GeneratedArtifact[]): Promise<string[]> {
  const produced = new Set(files.map((f) => f.relativePath));
  const removed: string[] = [];
  for (const relativePath of await listGeneratedFiles(outDir)) {
    if (produced.has(relativePath)) continue;
    const path = generatedPath(outDir, relativePath);
    const content = await readFile(path, 'utf8').catch(() => '');
    if (!content.startsWith(GENERATED_MARK)) continue;
    await rm(path);
    removed.push(path);
  }
  return removed;
}
